def seed_history(apps, schema_editor):
    # La última respuesta y revisión de cada tarea pasan al historial; antes se sobrescribían.
    alias = schema_editor.connection.alias
    Task = apps.get_model('core', 'CustomerTask')
    Entry = apps.get_model('core', 'CustomerTaskEntry')
    entries = []
    for task in Task._base_manager.using(alias).iterator():
        if task.response.strip():
            entries.append(Entry(task_id=task.pk, kind='response', status='submitted', text=task.response,
                                 created_at=task.submitted_at or task.updated_at))
        if task.review_note.strip():
            entries.append(Entry(task_id=task.pk, kind='review', status=task.status, text=task.review_note,
                                 author_id=task.reviewed_by_id, created_at=task.reviewed_at or task.updated_at))
    Entry._base_manager.using(alias).bulk_create(entries, batch_size=500)


